export type TrailLogoProps = {
  size?: number | string;
  title?: string;
  width?: number | string;
  height?: number | string;
  viewBox?: string;
  color?: string;
  className?: string;
  "aria-label"?: string;
  [key: string]: unknown;
};

export function TrailLogo({
  size,
  title,
  width,
  height,
  viewBox = "388 222 519 388",
  color = "#ff6a00",
  className,
  "aria-label": ariaLabel,
  ...props
}: TrailLogoProps) {
  const labelled = Boolean(title || ariaLabel);
  const resolvedWidth = width ?? size;
  const resolvedHeight = height ?? size;

  return (
    <svg
      {...props}
      className={className}
      width={resolvedWidth}
      height={resolvedHeight}
      viewBox={viewBox}
      color={color}
      role={labelled ? "img" : "presentation"}
      aria-hidden={labelled ? undefined : true}
      aria-label={ariaLabel ?? title}
      xmlns="http://www.w3.org/2000/svg"
    >
      {title ? <title>{title}</title> : null}
      <path
        d={TRAIL_LOGO_PATH}
        fill="currentColor"
        fillRule="evenodd"
        stroke="currentColor"
        strokeWidth="0.25"
        strokeLinejoin="round"
      />
    </svg>
  );
}
